#!/usr/bin/env node
// Generate every install manifest (and the version pinned in the skill shim)
// from package.json, the single source of truth for name/version/description.
//
//   npm run manifests        rewrite the generated files
//   npm run test:manifests   fail if a generated file drifted (CI + npm test)
//
// Six manifests, three install channels. The plugin itself lives under
// plugin/ and both catalogs at the repo root point there ("./plugin"), so a
// host copies only that folder: no package.json travels with the plugin, and
// npx run from the plugin root cannot mistake it for a local project (ADR-0011).
//   .claude-plugin/marketplace.json (root catalog)
//   plugin/.claude-plugin/plugin.json + plugin/.mcp.json
//       Claude Code plugin
//   .agents/plugins/marketplace.json (root catalog; Codex only installs
//       through a catalog, a bare folder under ~/.codex/plugins is not discovered)
//   plugin/plugin.json + plugin/mcp.json
//       Codex / Agent Plugins 1.0
//   (npx skills add reads the Claude catalog and copies plugin/skills/ only —
//   no MCP registration, CLI fallback)
//
// Both MCP manifests run the same shim with no arguments instead of calling npx
// directly: bin.js with no arguments is the MCP stdio server, so ARCHDRAW_BIN
// reaches the MCP path too (ADR-0002). Only manifest args are substituted by the
// hosts (Claude ${CLAUDE_PLUGIN_ROOT}, Codex ${PLUGIN_ROOT}) — SKILL.md is not.

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const repoRoot = path.dirname(path.dirname(fileURLToPath(import.meta.url)));
const pkg = JSON.parse(fs.readFileSync(path.join(repoRoot, 'package.json'), 'utf-8'));

const SKILL_NAME = 'archdraw';
// Server key in both MCP manifests: hosts expose the tools under this name, and
// SKILL.md tells the agent to look for archdraw tools before falling back.
const MCP_SERVER_NAME = 'archdraw';
// Where the plugin lives in the repo; both catalogs point here.
const PLUGIN_DIR = 'plugin';
// Shim path relative to the plugin root — what the MCP manifests reference.
const SHIM_REL = `skills/${SKILL_NAME}/scripts/${SKILL_NAME}`;

const AGENT_PLUGINS_SCHEMA = 'https://agent-plugins.org/schemas/1.0.0';
const MARKETPLACE_SCHEMA = 'https://anthropic.com/claude-code/marketplace.schema.json';

const repositoryUrl = String(pkg.repository?.url ?? pkg.repository ?? '')
  .replace(/^git\+/, '')
  .replace(/\.git$/, '');

const author = {
  ...(pkg.author?.name ? { name: pkg.author.name } : {}),
  ...(pkg.author?.email ? { email: pkg.author.email } : {}),
  ...(pkg.author?.url ? { url: pkg.author.url } : {})
};

const json = (value) => JSON.stringify(value, null, 2) + '\n';

// Claude and Codex want the same eight facts about the plugin; only Codex adds
// the Agent Plugins schema identifier.
const pluginManifest = (schema) => json({
  ...(schema ? { $schema: schema } : {}),
  name: pkg.name,
  version: pkg.version,
  description: pkg.description,
  author,
  homepage: pkg.homepage,
  repository: repositoryUrl,
  license: pkg.license,
  keywords: pkg.keywords
});

// Both hosts launch the same shim with no arguments. `command` stays one
// executable token because Agent Plugins 1.0 §7.2.1 forbids placeholder
// expansion there; the shim path travels in `args`, which both hosts expand.
const mcpManifest = ({ schema, rootVar }) => json({
  ...(schema ? { $schema: schema } : {}),
  mcpServers: {
    [MCP_SERVER_NAME]: {
      type: 'stdio',
      command: 'sh',
      args: [`\${${rootVar}}/${SHIM_REL}`]
    }
  }
});

const claudePlugin = pluginManifest();

const claudeMarketplace = json({
  $schema: MARKETPLACE_SCHEMA,
  name: pkg.name,
  description: pkg.description,
  owner: author,
  plugins: [
    {
      name: pkg.name,
      source: `./${PLUGIN_DIR}`,
      description: pkg.description,
      author,
      homepage: pkg.homepage
    }
  ]
});

const claudeMcp = mcpManifest({ rootVar: 'CLAUDE_PLUGIN_ROOT' });

const codexPlugin = pluginManifest(`${AGENT_PLUGINS_SCHEMA}/plugin.schema.json`);

const codexMcp = mcpManifest({
  schema: `${AGENT_PLUGINS_SCHEMA}/mcp.schema.json`,
  rootVar: 'PLUGIN_ROOT'
});

// Codex catalog: `codex plugin marketplace add LeeJuOh/excalidraw-architect`
// reads this file from the repo, then `codex plugin add <name>@<name>` installs
// the plugin whose root is plugin/.
const codexMarketplace = json({
  name: pkg.name,
  interface: { displayName: pkg.name },
  plugins: [
    {
      name: pkg.name,
      source: { source: 'local', path: `./${PLUGIN_DIR}` },
      policy: { installation: 'AVAILABLE' }
    }
  ]
});

const shim = `#!/bin/sh
# Generated by scripts/generate-manifests.mjs — run \`npm run manifests\` after a
# version bump; the pinned version below comes from package.json.
#
# No arguments  -> MCP stdio server (how both MCP manifests launch it)
# <command> ... -> CLI fallback, called as \`scripts/${SKILL_NAME} <command>\` from the
#                  skill root by hosts that did not register the MCP server.
#
# ARCHDRAW_BIN=<repo>/dist/bin.js runs a local build instead of the published
# package, on both paths (ADR-0002). Note the host process must inherit it, so
# start claude/codex from a shell that has it.
set -e

if [ -n "\${ARCHDRAW_BIN:-}" ]; then
  exec node "$ARCHDRAW_BIN" "$@"
fi

exec npx --prefix "$(dirname "$0")" -y ${pkg.name}@${pkg.version} "$@"
`;

/** @type {{ path: string, content: string, mode?: number }[]} */
const artifacts = [
  { path: `${PLUGIN_DIR}/.claude-plugin/plugin.json`, content: claudePlugin },
  { path: '.claude-plugin/marketplace.json', content: claudeMarketplace },
  { path: `${PLUGIN_DIR}/.mcp.json`, content: claudeMcp },
  { path: `${PLUGIN_DIR}/plugin.json`, content: codexPlugin },
  { path: `${PLUGIN_DIR}/mcp.json`, content: codexMcp },
  { path: '.agents/plugins/marketplace.json', content: codexMarketplace },
  { path: `${PLUGIN_DIR}/${SHIM_REL}`, content: shim, mode: 0o755 }
];

const checkOnly = process.argv.includes('--check');
const stale = [];

for (const artifact of artifacts) {
  const target = path.join(repoRoot, artifact.path);
  const current = fs.existsSync(target) ? fs.readFileSync(target, 'utf-8') : null;
  const modeOk =
    artifact.mode === undefined ||
    (current !== null && (fs.statSync(target).mode & 0o777) === artifact.mode);

  if (current === artifact.content && modeOk) continue;

  if (checkOnly) {
    stale.push(current === null ? `${artifact.path} (missing)` : artifact.path);
    continue;
  }

  fs.mkdirSync(path.dirname(target), { recursive: true });
  fs.writeFileSync(target, artifact.content);
  if (artifact.mode !== undefined) fs.chmodSync(target, artifact.mode);
  console.log(`wrote ${artifact.path}`);
}

if (checkOnly) {
  if (stale.length > 0) {
    console.error('Generated files are out of date:');
    for (const name of stale) console.error(`  - ${name}`);
    console.error('Run `npm run manifests` and commit the result.');
    process.exit(1);
  }
  console.log(`Generated files match package.json (${artifacts.length} files).`);
}
